void start_cfg ( void ) { struct client * c ; u_int i ; cfg_client = c = TAILQ_FIRST ( & clients ) ; if ( c != NULL ) { cfg_item = cmdq_get_callback ( cfg_client_done , NULL ) ; cmdq_append ( c , cfg_item ) ; } for ( i = 0 ; i < cfg_nfiles ; i ++ ) { if ( cfg_quiet ) { load_cfg ( cfg_files [ i ] , c , NULL , CMD_PARSE_QUIET , NULL ) ; } else { load_cfg ( cfg_files [ i ] , c , NULL , 0 , NULL ) ; } } cmdq_append ( cmdq_get_callback ( cfg_done , NULL ) ) ; } 